 function entityModal(type,id,prefillParent){MCQ.assert(type);const x=MCQ.get(type,id)||{},parent=MCQ.parents[type];UI.modal(id?'Edit '+names[type].toLowerCase():'Add '+names[type].toLowerCase(),`<form data-form="entity" data-type="${type}" data-id="${id||''}">${field('entity-name','Name',x.name||'','text',true)}<div class="field"><label>Icon</label><div class="icon-editor"><div class="icon-preview" id="entity-icon-preview">${UI.entityIcon(x,'grid')}</div><div class="grow">${field('entity-icon','Characters / emoji',/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(String(x.icon||''))?'':(x.icon||''),'text',false,'maxlength="4" placeholder="1–4 characters, e.g. CS or 📚"')}<label class="btn sm" for="entity-icon-file">Upload image</label><input class="visually-hidden" id="entity-icon-file" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="entity-icon-data" value="${/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(String(x.icon||''))?e(x.icon):''}"><p class="small muted">Use either 1–4 characters/emoji or upload a PNG, JPG or WebP image. Uploaded images appear in the oval card image area. Typing characters replaces the image.</p></div></div></div><label class="check-line"><input type="checkbox" name="entity-active" ${x.active!==false?'checked':''}> Enabled / visible</label>${['categories','papers'].includes(type)?select('entity-country','Country',[{id:'Both',name:'Both countries'},{id:'Pakistan',name:'Pakistan'},{id:'India',name:'India'}],x.country||(type==='categories'?'Both':'Pakistan'),true):''}${parent?select('entity-parent','Parent '+names[parent[0]].toLowerCase(),MCQ.db[parent[0]],x[parent[1]]||prefillParent||'',true):''}<div id="entity-state" role="status"></div><div class="actions"><button class="btn primary">Save record</button>${id&&MCQ.allowed(type)?btn(icon('trash')+' Delete','entity-delete','danger',`data-type="${type}" data-id="${id}"`):''}${btn('Cancel','close','')}</div></form>`)}
 function entityState(){const f=document.querySelector('form[data-form="entity"]');if(!f)return;const type=f.dataset.type,id=f.dataset.id,name=f.querySelector('[name="entity-name"]').value,parent=f.querySelector('[name="entity-parent"]')?.value;const dup=MCQ.duplicate(type,name,parent,id);const el=document.getElementById('entity-state');if(dup)el.innerHTML=`<div class="notice warning"><strong>Already exists: ${e(dup.name)}</strong><div class="actions" style="margin-top:10px">${btn('Use existing','use-entity','sm',`data-type="${type}" data-id="${dup.id}"`)}${btn('Edit existing','entity-edit','sm',`data-type="${type}" data-id="${dup.id}"`)}${link(({categories:'category',papers:'paper',jobs:'job',years:'year'})[type]+'/'+dup.id,'View','btn sm')}</div></div>`;else{const possible=MCQ.list(type,name).filter(x=>name&&x.id!==+id).slice(0,3);el.innerHTML=name?`<div class="notice ${possible.length?'warning':'success'}">${possible.length?'Possible match: '+possible.map(x=>e(x.name)).join(' · '):'New record. No exact match.'}</div>`:''}}
 function importPage(){return heading('Bulk Import MCQs','Upload, validate, import and approve MCQs in one place.')+`<div class="notice">One workflow: upload → validate → import as Pending → select imported MCQs → approve. Repeated questions merge their Paper / Job / Job Year mappings instead of creating another MCQ.</div><div class="steps">${['Upload','Parse','Preview','Validate','Duplicate check','Import'].map((s,i)=>`<span class="step ${App.importRows&&i<5?'done':''}">${i+1}. ${s}</span>`).join('')}</div><div class="card"><div class="section-head"><h3>Choose your file</h3><div class="actions">${['txt','csv','json'].map(ext=>btn(ext.toUpperCase()+' template','import-template','sm',`data-ext="${ext}"`)).join('')}</div></div><div class="dropzone" id="dropzone"><span class="tile-icon">${icon('upload')}</span><h3>Drop a file here, or browse</h3><p class="small muted">UTF-8 TXT, CSV or JSON · up to 5 MB</p><input type="file" id="import-file" accept=".txt,.csv,.json" aria-label="Upload MCQ file"></div><div id="import-results">${App.importRows?importPreview():'<p class="small muted">Each question needs four options, a matching correct answer, and complete category and paper links.</p>'}</div></div>`}
 function importPreview(){const rows=App.importRows||[],actionable=rows.filter(x=>x.status==='valid'||x.status==='merge'),s=App.importSummary||{total:rows.length,valid:rows.filter(x=>x.status==='valid').length,merge:rows.filter(x=>x.status==='merge').length,imported:0,merged:0,duplicates:0,invalid:rows.filter(x=>x.status==='invalid').length,failed:0},imported=(App.importedIds||[]).map(id=>MCQ.get('mcqs',id)).filter(Boolean),pending=imported.filter(q=>q.status==='pending'||q.pending_update);return `<div class="status-grid">${Object.entries(s).map(([l,n])=>`<div class="card"><span class="small muted">${l[0].toUpperCase()+l.slice(1)}</span><strong>${n}</strong></div>`).join('')}</div><div class="toolbar" style="margin-top:20px">${btn('Process '+actionable.length+' rows','import-commit','primary',actionable.length?'':'disabled')}${btn('Download validation report','import-report','')}<span class="small muted">Repeated questions are merged into one MCQ. Only new Paper / Job / Job Year links are added; invalid rows are skipped.</span></div><div class="table-wrap mobile-cards"><table><thead><tr><th>Row</th><th>Question</th><th>Result</th><th>Validation</th></tr></thead><tbody>${rows.slice(0,100).map(r=>`<tr><td data-label="Row">${r.line}</td><td data-label="Question">${e(r.question)}</td><td data-label="Status">${badge(r.status,r.status==='invalid'||r.status==='failed'?'rejected':r.status==='valid'||r.status==='imported'||r.status==='merged'?'approved':'pending')}</td><td data-label="Validation">${r.errors.map(e).join(' ')}${r.existing?link(url('edit/'+r.existing),'Open existing','btn sm'):''}</td></tr>`).join('')}</tbody></table></div>${rows.length>100?'<p class="small muted">Showing the first 100 rows. Download the report for all rows.</p>':''}${imported.length?`<section class="import-approval-panel"><div class="section-head"><div><p class="eyebrow">IMPORTED MCQS</p><h3>Approve without leaving this page</h3><p class="small muted">${pending.length} pending · ${imported.length} imported / merged in the last run.</p></div></div>${pending.length?`<div class="toolbar"><label class="check-line"><input type="checkbox" data-action="select-all" aria-label="Select all imported pending MCQs"> Select all imported</label><span class="small muted" id="selection-count">0 selected</span>${MCQ.allowed('approve')?btn('Approve selected','bulk-review','primary','data-status="approved"'):''}</div>`:''}<div class="table-wrap mobile-cards"><table><thead><tr><th>Select</th><th>Question</th><th>Job Years</th><th>Status</th></tr></thead><tbody>${imported.map(q=>`<tr><td>${q.status==='pending'||q.pending_update?`<input type="checkbox" class="row-check" value="${q.id}" aria-label="Select MCQ ${q.id}">`:''}</td><td data-label="Question"><strong>${e(q.question)}</strong></td><td data-label="Job Years">${MCQ.ids(q.job_years_ids).map(id=>e(MCQ.get('years',id)?.name||id)).join(', ')||'—'}</td><td data-label="Status">${badge(q.pending_update?'pending':q.status)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
 async function loadFile(file){if(!file)return;if(file.size>5*1024*1024){UI.toast('Choose a file smaller than 5 MB.');return}const box=document.getElementById('import-results');box.innerHTML='<div class="skeleton" role="status" aria-label="Parsing file"></div>';try{const raw=Importer.parse(await file.text(),file.name.split('.').pop().toLowerCase());if(raw.length>10000)throw Error('Use at most 10,000 rows per import.');App.importSummary=null;App.importRows=Importer.preview(raw);box.innerHTML=importPreview()}catch(err){App.importRows=null;box.innerHTML=`<div class="notice error" role="alert">${e(err.message)}</div>`}}
